export type Card = { monster: string; rank?: number };

const SPHINX = "sphinx";

function countTypes(army: Card[]): number {
  return new Set(army.map((card) => card.monster)).size;
}

export function sphinxScore(army: Card[]): number {
  const hasSphinx = army.some((card) => card.monster === SPHINX);
  if (!hasSphinx) return 0;

  const typeCount = countTypes(army);
  return typeCount > 3 ? typeCount - 2 : 2;
}

