const BASE_POINTS = 1;
const TYPE_THRESHOLD = 3;

function countOtherTypes(army: Card[]): number {
  const otherMonsters = army
    .map((card) => card.monster)
    .filter((monster) => monster !== SPHINX);
  return new Set(otherMonsters).size;
}

function typeBonus(otherTypes: number): number {
  if (otherTypes > TYPE_THRESHOLD) return 2 * (otherTypes - TYPE_THRESHOLD);
  return 1;
}

export function sphinxScore(army: Card[]): number {
  const hasSphinx = army.some((card) => card.monster === SPHINX);
  if (!hasSphinx) return 0;

  return BASE_POINTS + typeBonus(countOtherTypes(army));
}

