export type Card = { monster: string; rank?: number };

const SPHINX = "sphinx";

const BASE_POINTS = 1;
const TYPE_THRESHOLD = 3;

function isSphinx(card: Card): boolean {
  return card.monster === SPHINX;
}

function countTypesSeenBy(sphinxIndex: number, army: Card[]): number {
  const otherMonsters = army
    .filter((_, index) => index !== sphinxIndex)
    .map((card) => card.monster);
  return new Set(otherMonsters).size;
}

function typeBonus(otherTypes: number): number {
  if (otherTypes > TYPE_THRESHOLD) return 2 * (otherTypes - TYPE_THRESHOLD);
  return 1;
}

export function sphinxScore(army: Card[]): number {
  return army.reduce((score, card, index) => {
    if (!isSphinx(card)) return score;
    return score + BASE_POINTS + typeBonus(countTypesSeenBy(index, army));
  }, 0);
}

